#!/usr/bin/env python3
"""Clarify ordinary-city vs metropolitan-context anchor labels; preserve route request."""
from pathlib import Path
import pandas as pd,json,hashlib
H=Path(__file__).resolve().parent;P=H/'source_mass_preflight'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
s=P/'seventh_source_only_potential_destinations.parquet';out=P/'seventh_potential_destinations_routing_ready.parquet';assert not out.exists();x=pd.read_parquet(s);x['large_city_accessibility_anchor']=x.large_city_context_anchor;x['large_city_context_anchor']=x.id.isin(['ctx:RU-FED-MOW','ctx:RU-FED-SPB']);assert x.id.is_unique and len(x)==17491;x.to_parquet(out,index=False);old=pd.read_parquet(s);assert old.drop(columns=['large_city_context_anchor']).equals(x[old.columns].drop(columns=['large_city_context_anchor']));r=dict(status='ANCHOR_LABEL_CLARIFICATION_ONLY_IDS_COORDS_BUDGETS_UNCHANGED',source_sha256=sha(s),output_sha256=sha(out),large_city_accessibility_anchors=int(x.large_city_accessibility_anchor.sum()),external_metropolitan_context_anchors=int(x.large_city_context_anchor.sum()),potential_destinations=len(x),new_vs_six=int(x.new_vs_original_six_destinations.sum()),existing_budget_upgrade_requests=int(x.existing_budget_upgrade_needed.sum()),no_mass_or_eligibility_or_routing_budget_change=True,code_sha256=sha(Path(__file__)));(P/'routing_point_metadata_clarification.json').write_text(json.dumps(r,indent=2)+'\n');(P/'routing_point_metadata_addendum_freeze.json').write_text(json.dumps({'files':{str(p.name):sha(p) for p in [out,P/'routing_point_metadata_clarification.json',Path(__file__)]}},indent=2)+'\n');print(json.dumps(r,indent=2))
